if (msg.payload.feeds && msg.payload.feeds.length > 0) {
    var f = msg.payload.feeds[0];
    var t = parseFloat(f.field1);
    var s = parseFloat(f.field2);
    var h = parseFloat(f.field3);

    // Dynamically load thresholds from alert_generator (stored in flow context)
    // Fallback to defaults from alert_generator config.json if not yet loaded
    var th = flow.get("thresholds") || {
        temperature:   { min: 18, max: 30 },
        soil_moisture: { min: 30, max: 80 },
        humidity:      { min: 40, max: 80 }
    };

    var alert = (
        isNaN(t) || t < th.temperature.min   || t > th.temperature.max ||
        isNaN(s) || s < th.soil_moisture.min || s > th.soil_moisture.max ||
        isNaN(h) || h < th.humidity.min      || h > th.humidity.max
    );

    return [
        { payload: t },
        { payload: s },
        { payload: h },
        { payload: alert, topic: "raspi-01" }
    ];
}
return null;

if (msg.payload.feeds) {
    let t = [], s = [], h = [];
    msg.payload.feeds.forEach(f => {
        let time = new Date(f.created_at).getTime();
        if(f.field1) t.push({x: time, y: parseFloat(f.field1)});
        if(f.field2) s.push({x: time, y: parseFloat(f.field2)});
        if(f.field3) h.push({x: time, y: parseFloat(f.field3)});
    });

    // 构造 Chart 节点接受的数组格式
    return [
        { payload: [{ "series": ["Temperature"], "data": [t], "labels": ["Temperature"] }] },
        { payload: [{ "series": ["Soil Moisture"], "data": [s], "labels": ["Soil Moisture"] }] },
        { payload: [{ "series": ["Humidity"], "data": [h], "labels": ["Humidity"] }] }
    ];
}
