var alerts = flow.get("monitor_alerts") || {};
if (msg.topic) {
    alerts[msg.topic] = !!msg.payload;
    flow.set("monitor_alerts", alerts);
}
var anyAlert = Object.keys(alerts).some(function(k){ return alerts[k]; });
var last = flow.get("last_any_alert");
if (anyAlert !== last) {
    flow.set("last_any_alert", anyAlert);
    return { payload: anyAlert };
}
return null;

// Store thresholds from alert-generator config into flow context
// Expected shapes:
// 1. { thresholds: { temperature: {min,max}, soil_moisture: {...}, humidity: {...} } }
// 2. direct { temperature: {...}, soil_moisture: {...}, humidity: {...} }

var payload = msg.payload || {};
var thresholds = null;

if (payload.thresholds) {
    thresholds = payload.thresholds;
} else if (payload.temperature && payload.soil_moisture && payload.humidity) {
    thresholds = payload;
}

if (thresholds &&
    thresholds.temperature && thresholds.temperature.min != null && thresholds.temperature.max != null &&
    thresholds.soil_moisture && thresholds.soil_moisture.min != null && thresholds.soil_moisture.max != null &&
    thresholds.humidity && thresholds.humidity.min != null && thresholds.humidity.max != null) {

    flow.set("thresholds", thresholds);
    node.status({fill:"green", shape:"dot", text:"thresholds ready"});
    return null;
}

// Keep previous value / defaults on failure
node.status({fill:"yellow", shape:"ring", text:"using fallback thresholds"});
return null;

// Dynamically discover alert-generator endpoint from Catalog
// Fallback to hardcoded URL only when discovery fails (same pattern as Telegram Bot)

const FALLBACK_BASE = "http://alert-generator:8091";
const REQUEST_PATH = "thresholds";   // actual path that returns thresholds

let baseUrl = FALLBACK_BASE;

// msg.payload is the response from Catalog /services
const statusCode = msg.statusCode || (msg.response && msg.response.statusCode);

if (msg.payload && !msg.error && (!statusCode || statusCode === 200)) {
    try {
        let services = [];
        if (Array.isArray(msg.payload)) {
            services = msg.payload;
        } else if (msg.payload.services && Array.isArray(msg.payload.services)) {
            services = msg.payload.services;
        }

        for (let i = 0; i < services.length; i++) {
            const svc = services[i];
            const type = String(svc.type || "").trim().toLowerCase();
            if (type === "alert_generator") {
                const endpoint = String(svc.endpoint || "").trim();
                if (endpoint) {
                    baseUrl = endpoint.replace(/\/$/, "");
                    node.status({fill:"green", shape:"dot", text:"discovered"});
                    break;
                }
            }
        }
    } catch (e) {
        node.status({fill:"yellow", shape:"ring", text:"parse fail → fallback"});
    }
} else {
    node.status({fill:"yellow", shape:"ring", text:"catalog fail → fallback"});
}

// Build final URL: base + /thresholds
const configUrl = baseUrl.replace(/\/$/, "") + "/" + REQUEST_PATH;

// Pass the resolved URL to the next HTTP Request node
msg.url = configUrl;
msg.headers = msg.headers || {};
return msg;
